#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill for actual-mcp.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard will guide you through configuring .env, testing your\n' "$DIM"
  printf '  connection to Actual Budget, deploying via Docker Compose, and\n'
  printf '  connecting Google Gemini to your custom MCP endpoint.\n'
  printf '  Stop any time with Ctrl-C and re-run later (remembers saved values).%s\n\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps: $current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current secret]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ saved%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete!%s\n\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "Saved ${#WRITTEN_ENV[@]} configuration value(s) in $ENV_FILE"
  printf '\n%sNext steps on your VPS:%s\n' "$BOLD" "$RESET"
  say "1. Run: docker compose up -d"
  say "2. Verify health: curl -fsS http://127.0.0.1:${PORT:-3000}/healthz"
  say "3. Ensure Cloudflare Tunnel points your public hostname to http://localhost:${PORT:-3000}"
  say "4. Open Google Gemini > Settings > Connected Apps > Connect to an MCP server"
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

banner "Actual MCP Setup & Gemini Deployment Wizard"

# ── Stage 1: Public Domain & Port ──────────────────────────────────────────
stage "Public Domain & Local Port"
say "Actual MCP will be exposed over your Cloudflare Tunnel."
say "Enter the full public HTTPS URL configured in your Cloudflare Zero Trust tunnel."
note "Example: https://actual-mcp.yourdomain.com"
printf '\n'

ask PUBLIC_URL "Public HTTPS URL (no trailing slash):"
while [[ -z "$PUBLIC_URL" || "$PUBLIC_URL" != https://* ]]; do
  warn "PUBLIC_URL must start with https:// (e.g., https://actual-mcp.yourdomain.com)"
  ask PUBLIC_URL "Public HTTPS URL (no trailing slash):"
done
# Strip trailing slash if entered
PUBLIC_URL="${PUBLIC_URL%/}"
write_env PUBLIC_URL "$PUBLIC_URL"

printf '\n'
say "Select the local port on your VPS where actual-mcp should listen (default: 3000)."
ask PORT "Local host port:"
PORT="${PORT:-3000}"
write_env PORT "$PORT"

# Ensure DATA_DIR is configured
write_env DATA_DIR "/data"
write_env SYNC_TTL_SECONDS "30"

# ── Stage 2: OAuth 2.1 Credentials & Consent Passphrase ────────────────────
stage "OAuth 2.1 Credentials & Admin Passphrase"
say "Google Gemini connects using an OAuth Client ID & Client Secret."
say "When connecting, your browser will prompt for an Admin Passphrase on the consent page."
printf '\n'

EXISTING_CLIENT_ID=$(_existing "OAUTH_CLIENT_ID" || true)
if [[ -z "$EXISTING_CLIENT_ID" ]]; then
  DEFAULT_CLIENT_ID="gemini-actual-$(openssl rand -hex 4 2>/dev/null || echo "client")"
else
  DEFAULT_CLIENT_ID="$EXISTING_CLIENT_ID"
fi
ask OAUTH_CLIENT_ID "OAuth Client ID [$DEFAULT_CLIENT_ID]:"
OAUTH_CLIENT_ID="${OAUTH_CLIENT_ID:-$DEFAULT_CLIENT_ID}"
write_env OAUTH_CLIENT_ID "$OAUTH_CLIENT_ID"

EXISTING_SECRET=$(_existing "OAUTH_CLIENT_SECRET" || true)
if [[ -z "$EXISTING_SECRET" ]]; then
  DEFAULT_SECRET="$(openssl rand -hex 24 2>/dev/null || tr -dc 'a-zA-Z0-9' </dev/urandom | head -c 32)"
  step "Generated cryptographically random Client Secret."
  ask OAUTH_CLIENT_SECRET "OAuth Client Secret [Enter to use generated secret]:"
  OAUTH_CLIENT_SECRET="${OAUTH_CLIENT_SECRET:-$DEFAULT_SECRET}"
else
  ask_secret OAUTH_CLIENT_SECRET "OAuth Client Secret:"
fi
write_env OAUTH_CLIENT_SECRET "$OAUTH_CLIENT_SECRET"

printf '\n'
say "Choose an Admin Passphrase used to approve the OAuth connection on https://${PUBLIC_URL#https://}/authorize"
ask_secret OAUTH_ADMIN_PASSWORD "Admin Consent Passphrase:"
while [[ -z "$OAUTH_ADMIN_PASSWORD" ]]; do
  warn "Admin Passphrase cannot be empty."
  ask_secret OAUTH_ADMIN_PASSWORD "Admin Consent Passphrase:"
done
write_env OAUTH_ADMIN_PASSWORD "$OAUTH_ADMIN_PASSWORD"

# ── Stage 3: Actual Budget Sync Server ─────────────────────────────────────
stage "Actual Budget Sync Server Connection"
say "Configure your self-hosted Actual Budget server connection."
say "If actual-mcp runs on the same VPS, use host.docker.internal or your server URL."
note "Example: http://host.docker.internal:5006 or https://actual.yourdomain.com"
printf '\n'

ask ACTUAL_SERVER_URL "Actual Budget Server URL:"
while [[ -z "$ACTUAL_SERVER_URL" ]]; do
  warn "ACTUAL_SERVER_URL is required."
  ask ACTUAL_SERVER_URL "Actual Budget Server URL:"
done
ACTUAL_SERVER_URL="${ACTUAL_SERVER_URL%/}"
write_env ACTUAL_SERVER_URL "$ACTUAL_SERVER_URL"

printf '\n'
say "Enter your Actual Budget server password (used to log into Actual)."
ask_secret ACTUAL_PASSWORD "Actual Server Password:"
while [[ -z "$ACTUAL_PASSWORD" ]]; do
  warn "ACTUAL_PASSWORD is required."
  ask_secret ACTUAL_PASSWORD "Actual Server Password:"
done
write_env ACTUAL_PASSWORD "$ACTUAL_PASSWORD"

# ── Stage 4: Target Budget Sync ID & Encryption ────────────────────────────
stage "Target Budget Sync ID & Encryption"
say "Find your Sync ID in Actual Budget:"
step "Open Actual Budget in your browser or desktop app."
step "Go to Settings > Advanced > Sync ID (a UUID string)."
printf '\n'

ask ACTUAL_SYNC_ID "Paste your Budget Sync ID (UUID):"
while [[ -z "$ACTUAL_SYNC_ID" ]]; do
  warn "ACTUAL_SYNC_ID is required to open your budget."
  ask ACTUAL_SYNC_ID "Paste your Budget Sync ID (UUID):"
done
write_env ACTUAL_SYNC_ID "$ACTUAL_SYNC_ID"

printf '\n'
say "Is your budget protected with end-to-end encryption?"
if confirm "Does this budget have an E2E encryption password?"; then
  ask_secret ACTUAL_ENCRYPTION_PASSWORD "Enter Budget Encryption Password:"
  write_env ACTUAL_ENCRYPTION_PASSWORD "$ACTUAL_ENCRYPTION_PASSWORD"
else
  write_env ACTUAL_ENCRYPTION_PASSWORD ""
  note "End-to-end encryption password skipped."
fi

# ── Stage 5: Deployment Verification ───────────────────────────────────────
stage "Cloudflare Tunnel & Docker Startup"
say "Configuration has been saved to $ENV_FILE."
printf '\n'
step "Cloudflare Tunnel routing check:"
say "  In Cloudflare Zero Trust (or your VPS cloudflared config.yml):"
say "  Point hostname: ${PUBLIC_URL#https://}"
say "  To service:     http://localhost:${PORT:-3000}"
printf '\n'
step "To start or restart the container on your VPS:"
say "  docker compose pull && docker compose up -d"
say "  (or: docker compose up -d --build if building from source)"
printf '\n'
pause "Press Enter after you have started the container and Cloudflare Tunnel"

say "Testing health endpoint locally and publicly..."
if curl -fsS "http://127.0.0.1:${PORT:-3000}/healthz" >/dev/null 2>&1; then
  printf '  %s✓ Local healthcheck passed:%s http://127.0.0.1:%s/healthz\n' "$GREEN" "$RESET" "${PORT:-3000}"
else
  warn "Local healthcheck at http://127.0.0.1:${PORT:-3000}/healthz did not respond yet."
fi

if curl -fsS "${PUBLIC_URL}/healthz" >/dev/null 2>&1; then
  printf '  %s✓ Public healthcheck passed:%s %s/healthz\n' "$GREEN" "$RESET" "$PUBLIC_URL"
else
  warn "Public URL ${PUBLIC_URL}/healthz not reachable yet. Check your Cloudflare Tunnel route."
fi
pause "Press Enter to continue to Gemini connection details"

# ── Stage 6: Google Gemini Custom Connector Details ────────────────────────
stage "Connect to Google Gemini"
say "Open Google Gemini to connect your new MCP server:"
step "In Gemini, click Settings > Connected Apps (or https://gemini.google.com/devmode)"
step "Click 'Connect to an MCP server' (as shown in your screenshot)."
printf '\n'
say "%s──────────────── Copy & Paste into Gemini Modal ────────────────%s" "$BOLD" "$RESET"
say "  %sMCP server URL:%s  ${PUBLIC_URL}/mcp" "$BLUE" "$RESET"
say "  Click 'Additional settings / Show more':"
say "  %sClient ID:%s       ${OAUTH_CLIENT_ID}" "$BLUE" "$RESET"
say "  %sClient secret:%s   ${OAUTH_CLIENT_SECRET}" "$BLUE" "$RESET"
say "%s────────────────────────────────────────────────────────────────%s" "$BOLD" "$RESET"
printf '\n'
step "Click 'Next' in Gemini."
step "Your browser will redirect to ${PUBLIC_URL}/authorize"
step "Enter your Admin Consent Passphrase to approve the link."
step "Gemini will redirect back and complete the connection!"
printf '\n'
pause "Press Enter once you have connected in Gemini"

finish
}

run_wizard "$@"; exit
